CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, username TEXT NOT NULL UNIQUE, name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','chef','adjoint','scolarite','enseignant','etudiant','examens','commission')), password TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS groups(id INTEGER PRIMARY KEY,name TEXT NOT NULL,level TEXT NOT NULL,specialty TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS students(id INTEGER PRIMARY KEY,matricule TEXT NOT NULL UNIQUE,first_name TEXT NOT NULL,last_name TEXT NOT NULL,group_id INTEGER NOT NULL REFERENCES groups(id) ON DELETE RESTRICT,user_id INTEGER UNIQUE REFERENCES users(id) ON DELETE RESTRICT, status TEXT NOT NULL DEFAULT 'Inscrit');
CREATE TABLE IF NOT EXISTS teachers(id INTEGER PRIMARY KEY,name TEXT NOT NULL,grade TEXT NOT NULL,specialty TEXT NOT NULL,user_id INTEGER UNIQUE REFERENCES users(id) ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS sessions(id INTEGER PRIMARY KEY,day TEXT NOT NULL,start_time TEXT NOT NULL,end_time TEXT NOT NULL,module TEXT NOT NULL,kind TEXT NOT NULL,group_id INTEGER NOT NULL REFERENCES groups(id) ON DELETE RESTRICT,teacher_id INTEGER NOT NULL REFERENCES teachers(id) ON DELETE RESTRICT,room TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS absences(id INTEGER PRIMARY KEY,student_id INTEGER NOT NULL REFERENCES students(id) ON DELETE RESTRICT,session_id INTEGER NOT NULL REFERENCES sessions(id) ON DELETE RESTRICT,date TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('Non justifiée','Justifiée','En attente')),declared_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(student_id,session_id,date));
CREATE TABLE IF NOT EXISTS justifications(id INTEGER PRIMARY KEY,absence_id INTEGER NOT NULL REFERENCES absences(id) ON DELETE RESTRICT,reason TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('En attente','Accepté','Refusé')),file_key TEXT,file_name TEXT,decision_note TEXT,decided_by INTEGER REFERENCES users(id),decided_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS teacher_absences(id INTEGER PRIMARY KEY,teacher_id INTEGER NOT NULL REFERENCES teachers(id),date TEXT NOT NULL,session_id INTEGER NOT NULL REFERENCES sessions(id),status TEXT NOT NULL,note TEXT);
CREATE TABLE IF NOT EXISTS discipline(id INTEGER PRIMARY KEY,ref TEXT UNIQUE NOT NULL,student_id INTEGER NOT NULL REFERENCES students(id),incident_date TEXT NOT NULL,description TEXT NOT NULL,status TEXT NOT NULL,assigned_to INTEGER NOT NULL REFERENCES users(id),created_by INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE IF NOT EXISTS discipline_history(id INTEGER PRIMARY KEY,discipline_id INTEGER NOT NULL REFERENCES discipline(id),user_id INTEGER NOT NULL REFERENCES users(id),status TEXT NOT NULL,note TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),message TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,read_at TEXT);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY,user_id INTEGER REFERENCES users(id),action TEXT NOT NULL,target TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
